"""Self-contained white/Times architecture evidence report from executed tables."""
import argparse,base64,csv,html,itertools,json,math,os
from pathlib import Path
import numpy as np
from architecture_analysis import read,write,dump,sha

def load(path):return json.loads(path.read_text(encoding='utf-8')) if path.exists() else None
def table(rows,columns):
    def value(v):return f'{v:.3f}' if isinstance(v,float) else str(v)
    return '<table><thead><tr>'+''.join('<th>'+html.escape(label)+'</th>' for key,label in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(value(r.get(key,'')))+'</td>' for key,label in columns)+'</tr>' for r in rows)+'</tbody></table>'
def figure(path,caption,source):
    if not path.exists():return ''
    if Path(source).is_absolute():source=os.path.relpath(source,REPORT_BASE).replace('\\','/')
    data=base64.b64encode(path.read_bytes()).decode();return f'<figure><img src="data:image/png;base64,{data}" alt="{html.escape(caption)}"><figcaption>{html.escape(caption)} <a href="{html.escape(source)}">Numerical source</a>.</figcaption></figure>'

def run(args):
    global REPORT_BASE
    out=args.run/'architecture'/args.output_name;REPORT_BASE=out;summary=load(out/'architecture_summary.json')
    if not summary:raise ValueError('Run architecture analysis first')
    longitudinal=load(out/'longitudinal_architecture_summary.json');tracking=load(out/'tracking/tracking_summary.json');external=args.run/'architecture'/'external_pheno4d';instance=load(external/'external_correspondence_summary.json');rendered=load(external/'rendered/rendered_external_summary.json');exposure=load(external/'exposure/external_exposure_summary.json');negative=load(external/'uncertainty_and_negative_controls.json');known=load(args.run/'architecture'/'known_answer/known_answer_summary.json');geom=args.run/'architecture'/args.geometry_output_name/'geometry_diagnostics' if args.geometry_output_name is not None else out/'geometry_diagnostics';geometry=load(geom/'geometry_diagnostic_summary.json')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'serif','font.serif':['Times New Roman'],'font.size':11})
    figs=out/'figures';figs.mkdir(exist_ok=True);body=[];status='Full finalized extraction' if summary['mode']=='full_extraction' else 'PARTIAL / DEVELOPMENT INPUT: '+summary['mode']
    body.append('<h1>Architecture, organ correspondence and conditional exposure</h1><p class="status">'+html.escape(status)+'</p><p>We quantify what the full rotation observes, test geometry and correspondence assumptions, and evaluate fixed-receiver neighbour removal on independent known-ID laser geometry. CSI repeated labels remain candidate trajectories. The external component experiments supply the segmentation, plant continuity and geometry that CSI-maize currently lacks.</p>')
    body.append('<h2>Executed CSI denominator</h2>')
    facts=[dict(quantity='Input frame records',value=summary['input_rows']),dict(quantity='Accepted input masks',value=summary['accepted_input_rows']),dict(quantity='Observed camera sessions',value=summary['camera_sessions']),dict(quantity='Primary eligible camera sessions',value=summary['primary_eligible_camera_sessions']),dict(quantity='Strict eligible camera sessions',value=summary['strict_eligible_camera_sessions']),dict(quantity='Harmonic feature fits',value=summary['harmonic_fits']),dict(quantity='Mask/hash errors',value=summary['errors'])]
    if longitudinal:facts.extend([dict(quantity='Reference camera rows retained',value=longitudinal['reference_camera_rows']),dict(quantity='Five-visit candidate camera trajectories eligible',value=longitudinal['all_five_primary_eligible_camera_trajectories']),dict(quantity='All-forty accepted camera sessions for budgets',value=longitudinal['all40_accepted_camera_rows'])])
    body.append(table(facts,[('quantity','Quantity'),('value','Count')]))
    if longitudinal:
        rows=read(out/'coverage_selection_by_treatment_visit_camera.csv');image=np.zeros((6,5));names=[]
        for i,(t,c) in enumerate(itertools.product(['C','P','S'],['rgb','noir'])):
            names.append(t+' / '+c)
            for v in range(1,6):r=next(r for r in rows if r['treatment']==t and r['camera']==c and int(r['visit'])==v);image[i,v-1]=int(r['primary_eligible'])
        fig,ax=plt.subplots(figsize=(7,3.6));im=ax.imshow(image,vmin=0,vmax=24,cmap='Blues',aspect='auto');ax.set_xticks(range(5),range(1,6));ax.set_yticks(range(6),names);ax.set_xlabel('Recorded visit');ax.set_title('Eligible camera acquisitions / 24 reference identities per stratum')
        for y in range(6):
            for x in range(5):ax.text(x,y,str(int(image[y,x])),ha='center',va='center',color='white' if image[y,x]>12 else 'black')
        fig.colorbar(im,ax=ax,label='Acquisitions');fig.tight_layout();fig.savefig(figs/'coverage.png',dpi=170);plt.close(fig);body.append(figure(figs/'coverage.png','Coverage is counted against all 360 assay identities; missing measurements remain missing. Partial snapshots exclude entire unfinished acquisitions.','coverage_selection_by_treatment_visit_camera.csv'))
    harmonic_rows=read(out/'harmonic_descriptors.csv');profile=[]
    for camera,metric in itertools.product(['rgb','noir'],['area_fraction','height_fraction','width_fraction']):
        rr=[r for r in harmonic_rows if r['camera']==camera and r['metric']==metric and r['status']=='fit'];ranges=[float(r['directional_range_over_mean']) for r in rr];errors=[float(r['heldout_rmse'])/abs(float(r['mean'])) for r in rr if r.get('heldout_rmse') and float(r['mean'])!=0]
        if ranges:profile.append(dict(camera=camera,metric=metric,camera_sessions=len(rr),median_range_over_mean=float(np.median(ranges)),q25_range_over_mean=float(np.percentile(ranges,25)),q75_range_over_mean=float(np.percentile(ranges,75)),median_heldout_rmse_over_mean=float(np.median(errors)) if errors else None))
    if profile:
        write(out/'directional_observability_summary.csv',profile);fig,ax=plt.subplots(figsize=(7,3.6));xx=np.arange(3)
        for camera,offset,color in [('rgb',-.17,'#225d99'),('noir',.17,'#bd772c')]:
            rr=[next(r for r in profile if r['camera']==camera and r['metric']==m) for m in ['area_fraction','height_fraction','width_fraction']];values=np.array([r['median_range_over_mean'] for r in rr]);lo=values-np.array([r['q25_range_over_mean'] for r in rr]);hi=np.array([r['q75_range_over_mean'] for r in rr])-values;ax.bar(xx+offset,values,.32,color=color,label=camera);ax.errorbar(xx+offset,values,yerr=[lo,hi],fmt='none',ecolor='black',capsize=3)
        ax.set_xticks(xx,['Projected area','Visible height','Visible width']);ax.set_ylabel('Observed range / view mean');ax.set_title('Direction dependence across eligible camera acquisitions');ax.legend();fig.tight_layout();fig.savefig(figs/'directional_observability.png',dpi=180);plt.close(fig);body.append(figure(figs/'directional_observability.png','Bars are medians and whiskers are interquartile ranges across camera acquisitions. Height and width refer to visible image extent, without physical calibration.','directional_observability_summary.csv'))
    budget_rows=read(out/'view_budget_stability.csv');budget_summary=[]
    if budget_rows:
        for camera,metric,budget in itertools.product(['rgb','noir'],['area_fraction','width_fraction'],[4,8,12,20]):
            rr=[r for r in budget_rows if r['camera']==camera and r['metric']==metric and int(r['budget'])==budget];vals=[float(r['median_relative_error']) for r in rr];under=[float(r['max_underestimate_fraction']) for r in rr]
            if vals:budget_summary.append(dict(camera=camera,metric=metric,budget=budget,phase_rows=len(rr),camera_sessions=len(set(r['session'] for r in rr)),median_relative_error=float(np.median(vals)),p90_relative_error=float(np.percentile(vals,90)),p90_max_underestimate_fraction=float(np.percentile(under,90))))
        write(out/'view_budget_summary.csv',budget_summary);fig,axes=plt.subplots(1,2,figsize=(9,3.5))
        for ax,metric in zip(axes,['area_fraction','width_fraction']):
            for camera,color in [('rgb','#225d99'),('noir','#bd772c')]:
                rr=[r for r in budget_summary if r['camera']==camera and r['metric']==metric]
                if rr:ax.plot([r['budget'] for r in rr],[100*r['median_relative_error'] for r in rr],'-o',color=color,label=camera+' median');ax.plot([r['budget'] for r in rr],[100*r['p90_relative_error'] for r in rr],'--',color=color,label=camera+' 90th percentile')
            ax.set_title(metric.replace('_',' '));ax.set_xlabel('Nominal view budget');ax.set_xticks([4,8,12,20]);ax.set_ylabel('Relative error of view median (%)');ax.legend(fontsize=8)
        fig.tight_layout();fig.savefig(figs/'view_budget.png',dpi=180);plt.close(fig);body.append('<h2>Rotational observability and view budgets</h2><p>Angles are nominal index × 9 degrees. First/second harmonic fits use at least twenty accepted views across four quadrants. The budget experiment compares forty phase choices to each session’s full-forty accepted reference. The percentile curves describe those selected image observations; they are not confidence intervals or independent plant replicates.</p>');body.append(figure(figs/'view_budget.png','Budget errors use only sessions with all forty masks accepted; treatment/visit selection is audited separately.','view_budget_stability.csv'))
    body.append('<h2>Geometry adequacy</h2><p>We separate center-sampling aliasing, conservative voxel-cell bounds, camera families, mask uncertainty and capture assumptions. A zero/low strict hull does not demonstrate organ absence. Conservative cell boxes are an outer bound on geometric carving. Principal point, turn angles, rigid capture, axis and f=D remain conditional; silhouette agreement cannot establish anatomical 3D surfaces.</p>')
    if geometry:
        selected=read(geom/'train_selected_camera_diagnostic.csv');selected=[{**r,'train_median_iou':float(r['train_median_iou']),'heldout_median_iou':float(r['heldout_median_iou'])} for r in selected];body.append(table(selected,[('case','Acquisition'),('distance_over_height','D / height'),('roll_deg','Roll °'),('elevation_deg','Elevation °'),('train_median_iou','Train IoU'),('heldout_median_iou','Development held-out IoU')]))
        body.append('<p>The camera family is selected using training median IoU only; all alternatives are preserved. These are development silhouette predictions, without independent surface annotations. Raw voxel tests use 64/96/128 grids and an independently rasterized continuous thin-sheet scene.</p>')
    repeat=load(args.run/'architecture/geometry_domain_repeat/domain_repeat_summary.json') if summary['mode']=='full_extraction' else None
    if repeat:body.append('<p>A separate training-support audit found that the initial fixed horizontal domain was exceeded in 9/15 cases and the upper domain in 4/15. We retained that diagnostic and repeated the same camera family with domain bounds expanded from training masks alone. The repeat gave median case-level held-out IoU '+f"{repeat['median_case_heldout_iou']:.3f}"+' (range '+f"{repeat['heldout_case_range'][0]:.3f}"+' to '+f"{repeat['heldout_case_range'][1]:.3f}"+'). These remain conditional, discretized observation-model checks without anatomical truth.</p>')
    if known:body.append(figure(args.run/'architecture'/'known_answer/known_answer_stress_tests.png','Known-answer tests expose loss of recall under missing observations/perspective mismatch and the gap between silhouette prediction and true voxel geometry.',str(args.run/'architecture'/'known_answer/known_answer_summary.json')))
    if tracking:
        tcases=read(out/'tracking/tracking_cases.csv');positive=sum(r['status']=='executed' and int(r['track_hypotheses'])>0 for r in tcases)
        body.append('<h2>CSI terminal trajectories</h2><p>'+str(tracking['track_hypotheses'])+' unassisted image-path hypotheses were retained in '+str(positive)+' of '+str(tracking['executed_sessions'])+' evaluated RGB acquisitions. '+str(tracking['compatible_rows'])+' of '+str(tracking['heldout_rows'])+' held-out track/view observations met the fixed positional gate. This is unannotated endpoint compatibility, not physical leaf tracking accuracy. Cross-visit maps remain unselected. Missing/occluded paths are not counted as leaf deaths or births.</p>')
    if instance:
        body.append('<h2>External correspondence with supplied organ segmentation</h2><p>All seven original Pheno4D maize plants and their last two labelled dates are retained. We independently permute anonymous instances at each date. Numeric temporal IDs enter scoring only; no ID/rank/point-count feature enters matching. These registered, provided-instance experiments test correspondence as a component. They do not validate CSI segmentation, reconstruction or physical identity.</p>');rr=[r for r in instance['scores'] if r['scenario']=='original'];body.append(table(rr,[('scheme','Annotation'),('method','Fixed method'),('plant_pairs','Plant pairs'),('correct_links','Correct links'),('predicted_links','Predicted links'),('true_common_instances','True common'),('micro_precision','Precision'),('micro_recall','Recall')]))
    if negative:body.append('<p>The same geometry matcher accepted '+str(negative['wrong_plant_false_physical_links'])+' false physical correspondences out of '+str(negative['wrong_plant_possible_links'])+' possible links across '+str(negative['wrong_pair_annotation_comparisons'])+' wrong-plant comparisons ('+str(negative['unique_wrong_physical_ordered_pairs'])+' ordered physical pairs under both annotation conventions). An alternative-assignment margin of .5 retained both within-plant errors. Neither a small geometry cost nor a large margin can establish plant continuity.</p>')
    scaffold=load(external/'scaffold/external_scaffold_summary.json')
    if scaffold:
        body.append('<h2>Scale-free 3D terminal point scaffold</h2><p>We invert the already frozen sinusoid coefficients using the known orthographic render camera. '+str(scaffold['terminal_scaffold_points'])+' recovered points across fourteen scans were all closer to the correct annotated instance point support than to the nearest wrong instance. Median correct support distance was '+f"{scaffold['median_correct_instance_support_distance']:.4f}"+' scan heights (90th percentile '+f"{scaffold['p90_correct_instance_support_distance']:.4f}"+'), compared with median nearest-wrong-instance support distance '+f"{scaffold['median_nearest_wrong_instance_support_distance']:.3f}"+'. These are distances to observed real point support, not anatomical tip errors. The forty-point retained coverage remains part of the claim. No mesh, hidden surface, stem insertion or metric scale is inferred.</p>');body.append(figure(external/'scaffold/terminal_scaffold_known_geometry.png','Three projections of the frozen terminal point scaffold on real known geometry. Oracle colours/IDs enter scoring only.',str(external/'scaffold/terminal_scaffold_point_support.csv')))
        cross=load(external/'scaffold/automatic_scaffold_crossdate_summary.json')
        if cross:body.append('<p>Associating these automatically recovered scaffold points across the two dates gave '+str(cross['correct_crossdate_links'])+' correct links among '+str(cross['predicted_crossdate_links'])+' predictions. There were '+str(cross['recovered_true_common_instances'])+' true common instances among the recovered points, compared with '+str(cross['all_true_common_instances'])+' common instances in the full annotations. Overall recovery was therefore '+f"{100*cross['recall_among_all_true_common_instances']:.1f}"+'% under known rendering cameras and foreground semantics. It does not establish comparable performance on CSI images.</p>')
    if rendered:
        body.append('<h2>Real-geometry rendered terminal validation</h2><p>We rendered '+str(rendered['rendered_views'])+' known orthographic views from fourteen real laser scans. Leaf IDs affected z-buffer scoring only; fitting used silhouettes. '+str(rendered['track_hypotheses'])+' tracks were recovered from '+str(rendered['oracle_instances_with_8_train_terminal_views'])+' oracle instances with terminal observations in at least eight training views ('+str(rendered['true_tip_instances'])+' total instances across scans). All retained tracks had at least .8 training oracle purity. Correct ID plus position gate held for '+str(rendered['correct_mapped_organ_and_gate_all'])+'/'+str(rendered['heldout_track_rows'])+' held-out track/view rows, or '+str(rendered['correct_mapped_organ_and_gate_when_terminal_available'])+'/'+str(rendered['heldout_rows_with_mapped_organ_terminal'])+' when a terminal from the mapped organ was available. The missed-instance denominator is essential; the high conditional fraction is not full-organ recall.</p>');body.append(figure(external/'rendered/M01_0324_a_heldout.png','Fixed held-out rendered example: oracle instance colours; white markers show predicted terminal tracks. Static known geometry and supplied foreground semantics are prerequisites.',str(external/'rendered/heldout_oracle_organ_compatibility.csv')))
    if exposure:
        body.append('<h2>True-ID longitudinal neighbour dependencies</h2><p>Known point geometry supports actual fixed-shape, fixed-receiver neighbour removal: '+str(exposure['primary_visibility_rows'])+' receiver/direction states, '+str(exposure['primary_edge_rows'])+' removal edges, and '+str(exposure['true_id_crossdate_rows_available'])+' available true-ID cross-date edge comparisons. Each receiver’s potential point-splat footprint remains fixed within a removal. The collar stem remains blocking; tip-method regions include associated stem sections. Across dates, both region shape and arrangement change, so differences do not isolate a growth cause.</p>');body.append(figure(external/'exposure/neighbour_edges_leaf_collar.png','Known-ID mature blade-region dependencies, with the stem retained. Values average forty horizontal directions.',str(external/'exposure/mean_directional_neighbour_edges.csv')));body.append(figure(external/'exposure/neighbour_edges_leaf_tip.png','Known-ID tip-method annotation-region dependencies, including their associated stem sections.',str(external/'exposure/mean_directional_neighbour_edges.csv')));body.append(figure(external/'exposure/persistent_receiver3_removed4_polar.png','Prespecified receiver3 / removed4 across all seven plants, two dates. Fractions describe opaque projected exposure; no PAR or physiological absorption is inferred.',str(external/'exposure/fixed_shape_neighbour_removal_edges.csv')))
        sens=read(external/'exposure/grid_and_point_footprint_sensitivity.csv');ss=[]
        for scheme,splat in itertools.product(['leaf_collar','leaf_tip'],['0','1']):
            vals=np.array([float(r['absolute_gain_difference']) for r in sens if r['scheme']==scheme and r['splat_radius_px']==splat]);nonzero=vals[vals>0];ss.append(dict(scheme=scheme,radius128=splat,rows=len(vals),nonzero_rows=len(nonzero),p95_abs_difference=float(np.percentile(vals,95)),max_abs_difference=float(max(vals)),nonzero_median=float(np.median(nonzero)) if len(nonzero) else 0))
        write(external/'exposure/sensitivity_summary.csv',ss);body.append(table(ss,[('scheme','Annotation'),('radius128','128-grid splat radius'),('rows','Edge/direction comparisons'),('p95_abs_difference','95th percentile |Δ gain|'),('max_abs_difference','Maximum |Δ gain|'),('nonzero_median','Median among nonzero differences')]))
        body.append('<p>The worst raster/point-footprint sensitivity reaches '+f"{exposure['max_absolute_gain_fraction_sensitivity']:.3f}"+' of the receiver potential footprint. A median zero difference hides structurally zero edges. Pixel point-splat gaps, finite resolution and annotation boundaries limit the numerical interpretation. We do not infer calibrated leaf area, physical millimetres, irradiance, absorption or photosynthesis.</p>')
    body.append('<h2>Claim boundary and next evidence</h2><p>No additional CSI acquisition currently supports a validated true-organ removal/repositioning experiment. Camera/axis/angle/scale and capture-motion evidence, physical plant continuity, and independent tip/collar/rank/occlusion annotations are needed to connect the automatic CSI image pipeline to the known-geometry exposure component. The external result demonstrates the component with its prerequisites supplied; it does not fill these CSI validation gaps.</p><p><a href="https://www.ipb.uni-bonn.de/data/pheno4d/index.html">Original Pheno4D source</a>; <a href="https://doi.org/10.1371/journal.pone.0256340">Pheno4D paper</a>; <a href="https://github.com/AIS-Bonn/data_loaders/blob/master/src/DataLoaderPhenorob.cxx">official loader</a>; <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9730636/">PhenoTrack3D prior art</a>. External original scans remain separate and are not bundled into the CSI-maize data release. Article licensing is not assumed to establish dataset redistribution terms.</p>')
    style='body{font-family:"Times New Roman",Times,serif;background:white;color:#111;max-width:1120px;margin:40px auto;padding:0 28px;font-size:18px;line-height:1.45}h1{font-size:32px}h2{font-size:25px;margin-top:38px}table{border-collapse:collapse;width:100%;font-size:15px;margin:20px 0;overflow-wrap:anywhere}th,td{padding:8px;border:1px solid #bbb;text-align:left}th{background:#f2f2f2}figure{margin:28px 0}img{max-width:100%;height:auto;display:block;margin:auto}figcaption{font-size:16px;margin-top:9px}.status{border:1px solid #444;padding:10px;font-weight:bold}a{color:#174b7d}'
    content='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Architecture evidence investigation</title><style>'+style+'</style></head><body>'+''.join(body)+'</body></html>';path=out/'architecture_evidence_report.html';path.write_text(content,encoding='utf-8');dump(out/'architecture_report_manifest.json',dict(report=str(path),report_sha256=sha(path),script_sha256=sha(__file__),input_summary_sha256=sha(out/'architecture_summary.json'),mode=summary['mode'],figures=[str(p.relative_to(out)) for p in figs.glob('*.png')],external_originals_bundled=False));print(json.dumps(dict(report=str(path),bytes=path.stat().st_size,mode=summary['mode'])))

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--intake',type=Path,required=True);p.add_argument('--run',type=Path,required=True);p.add_argument('--output-name',default='');p.add_argument('--geometry-output-name');run(p.parse_args())
